    <main>
      <section class="quiz-shell" aria-labelledby="page-title">
        <div class="hero">
          <p class="eyebrow">Multiple-select quiz</p>
          <h1 id="page-title">Computer Languages Checkpoint</h1>
          <p class="intro">
            Choose every answer that applies for each question. Some questions
            may have more than one correct answer.
          </p>
        </div>

