      const quizQuestions = [
        {
          id: "language-types",
          prompt: "Which of these are programming languages?",
          helpText:
            "Select all options that are languages used to write computer programs.",
          choices: ["Python", "HTML", "JavaScript", "Photoshop"]
        },
        {
          id: "web-languages",
          prompt: "Which languages are commonly used to build web pages?",
          choices: ["HTML", "CSS", "JavaScript", "SQL"]
        },
        {
          id: "compiled-languages",
          prompt: "Which languages are often compiled before running?",
          choices: ["C++", "Rust", "Go", "Markdown"]
        }
      ];

      function Choice({ questionId, choice }) {
        const choiceId = `${questionId}-${choice.toLowerCase().replace(/[^a-z0-9]+/g, "-")}`;

        return `
          <label class="choice" for="${choiceId}">
            <input
              type="checkbox"
              id="${choiceId}"
              name="${questionId}"
              value="${choice}"
            >
            <span class="choice-text">${choice}</span>
          </label>
        `;
      }

      function Question({ id, prompt, helpText, choices }, index) {
        const legendId = `${id}-legend`;
        const helpId = `${id}-help`;
        const describedBy = helpText ? ` aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset${describedBy}>
              <legend id="${legendId}">${index + 1}. ${prompt}</legend>
              ${
                helpText
                  ? `<p class="help-text" id="${helpId}">${helpText}</p>`
                  : ""
              }
              <div class="choice-grid">
                ${choices.map((choice) => Choice({ questionId: id, choice })).join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

