        return questions
          .map((question, index) => Question(question, index))
          .join("");
      }

      const quizRoot = document.querySelector("#quiz-root");
      const quizForm = document.querySelector("#quiz-form");
      const result = document.querySelector("#result");

      quizRoot.innerHTML = QuizApp({ questions: quizQuestions });

      quizForm.addEventListener("submit", (event) => {
        event.preventDefault();

        const answeredCount = quizQuestions.filter((question) => {
          return quizForm.querySelectorAll(`input[name="${question.id}"]:checked`).length > 0;
        }).length;

        result.textContent = `You answered ${answeredCount} of ${quizQuestions.length} questions.`;
      });
    </script>
